// INPUT: binary file from readBinaryFiles node
// OUTPUT: { filename, content, doctype, chunked_at }

const items = $input.all();
return items.map(item => {
  const binary = item.binary;
  const propName = Object.keys(binary)[0];
  const data = binary[propName];
  const content = data.data ? Buffer.from(data.data, 'base64').toString('utf-8') : '';
  const filename = data.fileName || propName;
  const doctype = filename.replace(/^\d+-/, '').replace('.md', '').replace(/-/g, ' ');

  return {
    json: {
      filename: filename,
      content: content,
      doctype: doctype,
      chunked_at: new Date().toISOString()
    }
  };
});

// Split document into 500-token chunks with 50-token overlap
// Input: { filename, content }
// Output: one item per chunk with { text, chunk_index, filename, doctype }

const items = $input.all();
const chunks = [];

for (const item of items) {
  const { filename, content, doctype } = item.json;
  const words = content.split(/\s+/);
  const chunkSize = 500;
  const overlap = 50;
  let i = 0;

  while (i < words.length) {
    const chunk = words.slice(i, i + chunkSize).join(' ');
    chunks.push({
      json: {
        filename: filename,
        chunk_index: chunks.length,
        text: chunk,
        doctype: doctype,
        chunk_id: `${filename}#${chunks.length}`
      }
    });
    i += chunkSize - overlap;
  }
}

return chunks;

// Skip chunks that already exist in Supabase (dedup by chunk_id)
// If no Supabase connection yet, pass-through all chunks
// TODO: Replace with real Supabase dedup query in Phase 3

return $input.all();
